#!/usr/bin/env python3
"""Commit app/src/main/java/com/ivanna/omega/ui/MagiskStatusPanel.kt"""
import subprocess, base64, os, sys

os.chdir(os.path.expanduser("~/IVANNA-OMEGA-SUPREME"))

# Pull primero
r = subprocess.run(["git","pull","--rebase","origin","main"], capture_output=True, text=True)
print(r.stdout.strip())
if r.returncode != 0:
    print("ERROR pull:", r.stderr); sys.exit(1)

# Escribir archivo via base64 (sin heredoc, sin problemas de shell)
data = base64.b64decode("""""")
os.makedirs(os.path.dirname("app/src/main/java/com/ivanna/omega/ui/MagiskStatusPanel.kt") or ".", exist_ok=True)
with open("app/src/main/java/com/ivanna/omega/ui/MagiskStatusPanel.kt", "wb") as f:
    f.write(data)
print(f"✅ Escrito: app/src/main/java/com/ivanna/omega/ui/MagiskStatusPanel.kt ({len(data)} bytes)")

# Verificar que el archivo existe y tiene contenido
size = os.path.getsize("app/src/main/java/com/ivanna/omega/ui/MagiskStatusPanel.kt")
assert size > 100, f"Archivo muy pequeño: {size} bytes"

# git add
r = subprocess.run(["git","add","app/src/main/java/com/ivanna/omega/ui/MagiskStatusPanel.kt"], capture_output=True, text=True)
print(r.stdout, r.stderr)
if r.returncode != 0:
    print("ERROR add:", r.stderr); sys.exit(1)

# Verificar que hay cambios staged
r = subprocess.run(["git","status","--porcelain","app/src/main/java/com/ivanna/omega/ui/MagiskStatusPanel.kt"], capture_output=True, text=True)
if not r.stdout.strip():
    print("ℹ️  Sin cambios en app/src/main/java/com/ivanna/omega/ui/MagiskStatusPanel.kt (ya commitado)")
    sys.exit(0)
print("Staged:", r.stdout.strip())

# Commit
r = subprocess.run(["git","commit","-m","feat(ui): boton RECONECTAR + estado N/A sin Magisk + auto-probe polling"], capture_output=True, text=True)
print(r.stdout.strip())
if r.returncode != 0:
    print("ERROR commit:", r.stderr); sys.exit(1)

# Push
r = subprocess.run(["git","push","origin","main"], capture_output=True, text=True)
print(r.stdout.strip(), r.stderr.strip())
if r.returncode != 0:
    print("ERROR push:", r.stderr); sys.exit(1)
print("✅ Pushed: app/src/main/java/com/ivanna/omega/ui/MagiskStatusPanel.kt")
